final class LFUCache {
    private let capacity: Int
    private var values: [Int: (value: Int, freq: Int)] = [:]
    private var buckets: [Int: [Int]] = [:]      // freq -> keys, oldest first
    private var minFreq = 0

    init(_ capacity: Int) { self.capacity = capacity }

    func get(_ key: Int) -> Int {
        guard let entry = values[key] else { return -1 }
        touch(key, entry)
        return entry.value
    }

    func put(_ key: Int, _ value: Int) {
        guard capacity > 0 else { return }
        if let entry = values[key] { values[key] = (value, entry.freq); touch(key, (value, entry.freq)); return }
        if values.count == capacity, let evict = buckets[minFreq]?.first {
            buckets[minFreq]!.removeFirst()
            values[evict] = nil
        }
        values[key] = (value, 1)
        buckets[1, default: []].append(key)
        minFreq = 1
    }

    private func touch(_ key: Int, _ entry: (value: Int, freq: Int)) {
        buckets[entry.freq]!.removeAll { $0 == key }          // O(n) here; use a linked list + node map for O(1)
        if entry.freq == minFreq && buckets[entry.freq]!.isEmpty { minFreq += 1 }
        values[key] = (entry.value, entry.freq + 1)
        buckets[entry.freq + 1, default: []].append(key)
    }
}
